(function(){'use strict';
const C=IV,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=v=>new Intl.NumberFormat('fi-FI',{style:'currency',currency:'EUR'}).format((v||0)/100),pct=v=>new Intl.NumberFormat('fi-FI',{maximumFractionDigits:1}).format(v)+' %',dsp=d=>d?d.split('-').reverse().join('.'):'Ei kirjattu',amt=v=>v===null||v===undefined?'':(v/100).toFixed(2);
let state=C.empty(),db,view='overview',pending=null,lastImport='',mode='monthly',filter={search:'',cc:'',month:''},busy=false,storageError='',importGeneration=0;
function notify(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,6500);}
function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('ilmastovisio-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('state');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('Sulje sovelluksen muut välilehdet.'));});}
function getDB(){return new Promise((resolve,reject)=>{const q=db.transaction('state').objectStore('state').get('main');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function commit(next,message){if(busy){notify('Odota edellisen tallennuksen valmistumista.');return false;}if(!db||storageError){notify('Tallennus ei ole käytettävissä. Tietoja ei muutettu.');return false;}busy=true;$('#save-state').textContent='Tallennetaan…';try{C.validateState(next);next.revision=(state.revision||0)+1;await new Promise((resolve,reject)=>{let conflict=false;const tx=db.transaction('state','readwrite'),store=tx.objectStore('state'),q=store.get('main');q.onsuccess=()=>{if((q.result?.revision||0)!==(state.revision||0)){conflict=true;tx.abort();}else store.put(next,'main');};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(Error(conflict?'Tietoja muutettiin toisessa välilehdessä. Päivitä sivu ennen jatkamista.':'Tallennus epäonnistui.'));});state=next;render();notify(message||'Tallennettu tällä laitteella.');return true;}catch(e){notify(e.message);$('#save-state').textContent='Tallennus epäonnistui';return false;}finally{busy=false;}}
const clone=()=>JSON.parse(JSON.stringify(state));
function go(v){view=v;render();$('#main').focus();}
const button=(action,text,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
function head(title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow">Ilmastovisio / ${view==='overview'?'Koko hanke':title}</div><h1>${title}</h1><div class="sub">${sub}</div></div><div class="actions">${actions}</div></div>`;}
function metric(label,value,help='',cls=''){return `<div class="metric ${cls}"><div class="label">${label}</div><strong>${value}</strong><small>${help}</small></div>`;}
function line(label,value){return `<div class="rowline"><span>${label}</span><b>${value}</b></div>`;}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Ei tapahtumia.</td></tr>`}</tbody></table></div>`;}
const n=v=>`<div class="num">${euro(v)}</div>`;
function issues(){const a=[],s=state.settings;for(let i=0;i<state.funding.length;i++){const f=state.funding[i];if(f.decided!==null&&f.received>f.decided)a.push(f.funder+': saatu määrä ylittää päätetyn määrän jaksolla '+dsp(f.from)+'–'+dsp(f.to)+'.');for(const g of state.funding.slice(i+1))if(f.funder===g.funder&&f.from<=g.to&&g.from<=f.to)a.push(f.funder+': maksatusjaksoissa on päällekkäisyyttä. Tarkista rahoituserät.');}const count=state.rows.filter(r=>C.payroll(r,s)&&!r.reviewed).length;if(count)a.push(`${count} palkkarivin tukikelpoisuus on tarkistamatta. Rahoituslaskelma on alustava.`);const extras=state.rows.filter(r=>r.cc==='1682'&&C.expense(r)&&!C.payroll(r,s)&&!/^51/.test(r.account));if(extras.length)a.push(`Kustannuspaikalla 1682 on ${extras.length} muuta kuluriviä (${euro(extras.reduce((a,r)=>a+r.debit-r.credit,0))}). Ne näkyvät menoissa, eivät automaattisessa palkkapohjassa.`);const excluded=state.rows.filter(r=>r.date<s.start||r.date>s.end);if(excluded.length)a.push(`${excluded.length} riviä hankkeen ajanjakson ulkopuolella. Ne eivät sisälly hankkeen raportteihin.`);const nonexpense=state.rows.filter(r=>!C.expense(r));if(nonexpense.length)a.push(`${nonexpense.length} tase- tai tulotilin riviä. Menolaskenta sisältää tilit 4000–8999. Rahoituksen saannot kirjataan Rahoitus-osiossa.`);a.push(...C.balances(state.statements));if(!s.cutoff&&state.rows.length)a.push('Valitse asetuksissa viimeinen kokonaan kirjattu kuukausi ennustetta varten.');return a;}
function warnings(){const a=issues();return a.length?`<details class="notice warn"><summary>${a.length} tarkistettavaa huomiota</summary>${a.map(t=>`<p>${esc(t)}</p>`).join('')}</details>`:'';}
function overview(){const s=state.settings,t=C.totals(state.rows,s),f=C.forecast(state.rows,s),jf=C.fundingTotal(state.funding,'JTF'),tf=C.fundingTotal(state.funding,'Tulevaisuusrahasto'),received=jf.received+tf.received,unreceived=Math.max(0,t.basis-received);let html=head('Talouden tilannekuva',`${s.cutoff?'Seuranta '+dsp(s.cutoff)+' asti':'Kaikki tuodut hankekauden kirjaukset'} · Budjetti ${euro(s.budget)}`,button('nav-import','+ Tuo pääkirja','primary'));
 if(!state.rows.length)html+=`<section class="panel empty"><h2>Aloita omasta pääkirjastasi</h2><p class="sub">Tuo XLSX- tai CSV-tiedosto. Hankkeen budjetti ja laskentasäännöt ovat valmiina. Taloustiedot tallennetaan vain tähän selaimeen.</p>${button('nav-import','Valitse pääkirjat','primary')}</section>`;
 html+=warnings()+`<div class="metrics">${metric('Toteutuneet menot',euro(t.actual),'Kustannuspaikat 1682 + 1683','primary')}${metric('Hyväksyttävä kustannuspohja',euro(t.basis),'Laskennallinen arvio, sis. flat rate','leaf')}${metric('Saatu rahoitus yhteensä',euro(received),'Kirjatut maksut, kaikki jaksot')}${metric('Laskennallisesti saamatta',euro(unreceived),'Kustannuspohja − saatu rahoitus')}</div>`;
 html+=`<div class="grid2"><section class="panel"><div class="split"><h2>Menot kuukausittain</h2><span class="sub">${state.rows.length} tositeriviä</span></div>${bars()}<div class="legend"><span><i></i>1682</span><span><i class="light"></i>1683</span></div></section><section class="panel"><h2>Budjetin käyttö</h2><div class="budgetvalue"><strong>${pct(t.basis/s.budget*100||0)}</strong><span class="sub">kustannuspohjasta</span></div><div class="progress"><span style="width:${Math.max(0,Math.min(100,t.basis/s.budget*100||0))}%"></span></div>${line('Budjetista jäljellä',euro(s.budget-t.basis))}${line('Kirjanpidon menot / budjetti',pct(t.actual/s.budget*100||0))}${line('Palkkabudjetista jäljellä',euro(s.salaryBudget-t.salary))}<p class="sub">Budjettia verrataan palkkojen ja laskennallisen flat raten kustannuspohjaan. Kirjanpidon menot voivat poiketa siitä.</p></section></div>`;
 html+=`<div class="metrics">${metric('Laskennallinen JTF 80 %',euro(t.jtf),'Arvio ennen maksatuspäätöstä')}${metric('Tulevaisuusrahasto 20 %',euro(t.future),'Laskennallinen rahoitusosuus')}${metric('Flat rate -marginaali',euro(t.margin),'Flat rate 40 % − 1683:n menot','leaf')}${metric('Menojen ennuste loppuun',f?euro(f.actual):'Ei vielä arviota',f?`${f.remaining} tulevaa kuukautta`:'Aseta valmis kirjanpitokuukausi')}</div>`;
 html+=`<div class="grid2"><section class="panel"><h2>Mistä kustannuspohja muodostuu?</h2>${line('Palkkapohja ilman sivukuluja ja lomarahaa',euro(t.wage))}${line(`Vakiosivukulut ${s.sideRate.toLocaleString('fi-FI')} %`,euro(t.side))}${line('Hyväksyttävät palkkakustannukset, arvio',euro(t.salary))}${line('Flat rate 40 % palkkakustannuksista',euro(t.flat))}${line('Hyväksyttävä kustannuspohja, arvio',euro(t.basis))}${button('nav-transactions','Tarkista palkkarivit','link')}</section><section class="panel"><h2>Ennuste ja liikkumavara</h2>${f?`${line('Menojen kuukausivauhti',euro(f.monthly))}${line('Kustannuspohjan ennuste',euro(f.basis))}${line('Budjetti − kustannuspohjan ennuste',euro(s.budget-f.basis))}<p class="sub">Toteuma + jäljellä olevat kuukaudet × ${s.forecastMonthly===null?'viimeisten '+f.n+' kuukauden keskiarvo':'oma menoarvio'}. Kustannuspohjan ennuste käyttää aina viimeisten ${f.n} kuukauden keskiarvoa. Henkilöstömuutoksia ei ennakoida automaattisesti.</p>`:`<p class="sub">Vahvista viimeinen kokonaan kirjattu kuukausi. Voit myös asettaa tulevien kuukausien menoarvion.</p>`}${line('1682:n toteutuneet menot',euro(t.a))}${line('1683:n toteutuneet menot',euro(t.b))}${line('Flat rate − kaikki muut kulut¹',euro(t.margin-t.other1682))}<p class="sub">¹ Sisältää myös 1682:lle kirjatut muut kuin palkka- ja sivukulut.</p>${button('nav-settings','Muokkaa ennusteen oletuksia','link')}</section></div>`;
 if(t.jtf>s.jtfCap||t.future>s.futureCap)html+=`<p class="notice error">Laskennallinen rahoitus ylittää suunnitelman rahoitusosuuden. Arviota ei ole leikattu automaattisesti enimmäismäärään.</p>`;return html;}
function bars(){const rr=C.report(state.rows,state.settings).slice(-12),max=Math.max(...rr.map(r=>Math.max(0,r.a)+Math.max(0,r.b)),1);return rr.length?rr.map(r=>`<div class="bar-row"><span>${r.period.slice(5)}/${r.period.slice(2,4)}</span><div class="bar" aria-label="${esc(r.period+' '+euro(r.actual))}"><span class="a" style="width:${Math.max(0,r.a)/max*100}%"></span><span class="b" style="width:${Math.max(0,r.b)/max*100}%"></span></div><span class="num">${euro(r.actual)}</span></div>`).join(''):'<p class="sub">Kuukausittaiset menot näkyvät tuonnin jälkeen.</p>';}
function importPage(){return head('Pääkirjan tuonti','Tiedosto käsitellään tällä laitteella. Alku- ja loppusaldoja ei lasketa menoiksi.')+`<section class="panel"><h2>Tuo yksi tai useampi pääkirja</h2><p class="sub">Tuettu: maakuntaliiton ryhmitelty pääkirja sekä taulukkomuotoinen XLSX / CSV. Kaikki välilehdet tarkistetaan.</p><label class="dropzone">Valitse XLSX- tai CSV-tiedostot<input id="ledger-files" type="file" accept=".xlsx,.csv" multiple></label><div class="sub">CSV-sarakkeet: päivämäärä, kustannuspaikka, tili, tilin nimi, tosite, selite, debet, kredit. Jnro ja Tl kannattaa säilyttää, jos ne ovat saatavilla.</div><details><summary>Tuonnin toimintaperiaate</summary><p>Yhteissummat, tunnisterivit ja saldot ohitetaan. Kustannuspaikoista luetaan 1682 ja 1683, myös etunollilla. Summat ovat debet miinus kredit. Samat tositerivit tunnistetaan tiedoston nimestä riippumatta. Muuttunut tosite estää tuonnin, kunnes ristiriita on selvitetty.</p><p>Jos rivinumero puuttuu, täysin samanlaisten rivien lukumäärä säilytetään yhden aineiston sisällä. Erillisiä, kaikin tiedoin identtisiä uusia kirjauksia ei voi tunnistaa varmasti ilman rivinumeroa.</p></details>${button('download-template','Lataa CSV-pohja','link')}</section><div id="import-preview">${pending?preview():lastImport?`<p class="notice">${esc(lastImport)}</p>`:''}</div><section class="panel"><h2>Tuontihistoria</h2>${table(['Aika','Tiedostot','Uusia','Jo ennestään'],state.imports.slice().reverse().map(i=>[esc(new Date(i.date).toLocaleString('fi-FI')),esc(i.source),i.added,i.duplicates]))}</section>`;}
function preview(){const p=pending,errors=p.errors,conf=p.result.conflicts;return `<section class="panel"><h2>Tuonnin esikatselu</h2><p><b>${p.result.added}</b> uutta riviä · <b>${p.result.duplicates}</b> jo ennestään · ${p.other} muiden kustannuspaikkojen riviä ohitettu</p>${p.files.map(f=>`<p class="sub">${esc(f)}</p>`).join('')}${errors.length?`<div class="notice error"><b>Tuontia ei tallenneta ennen virheiden korjaamista.</b>${errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>`:''}${conf.length?`<div class="notice error"><b>${conf.length} ristiriitaista tositeriviä. Tuonti estetty.</b>${conf.map(c=>`<p>${esc(c.row.date+' / '+c.row.voucher+' / '+c.row.line)}: aiemmin ${euro(c.old.debit-c.old.credit)}, nyt ${euro(c.row.debit-c.row.credit)}. Tarkista Tapahtumat-näkymästä ja poista vanhentunut rivi vain, jos uusi versio korvaa sen.</p>`).join('')}</div>`:''}${C.balances([...state.statements,...p.statements]).map(t=>`<p class="notice warn">${esc(t)}</p>`).join('')}${table(['Kuukausi','1682 menot','1683 menot','Yhteensä'],C.report(p.newRows,{...state.settings,cutoff:''}).filter(r=>r.actual).map(r=>[esc(r.period),n(r.a),n(r.b),n(r.actual)]))}<p class="sub">Taulukko sisältää vain uudet hankekauden menot. Tarkista varsinkin palkat ja mahdolliset lomarahat tuonnin jälkeen.</p><div class="actions">${button('commit-import','Tallenna tuonti','primary',errors.length||conf.length?'disabled':'')}${button('cancel-import','Peruuta')}</div></section>`;}
async function loadFiles(files){const generation=++importGeneration;pending=null;$('#import-preview').innerHTML='<p class="notice">Luetaan ja tarkistetaan tiedostoja…</p>';let rows=[],errors=[],statements=[],other=0,filesList=[];for(const file of files){filesList.push(file.name);try{if(file.size>25*1024*1024)throw Error('Tiedosto ylittää 25 Mt enimmäiskoon');const bytes=await file.arrayBuffer();let sheets;if(/\.xlsx$/i.test(file.name))sheets=await readXLSX(bytes);else if(/\.csv$/i.test(file.name)){let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{text=new TextDecoder('windows-1252').decode(bytes);}sheets=[{name:'CSV',grid:C.parseCSV(text)}];}else throw Error('Vain XLSX ja CSV ovat tuettuja');for(const sheet of sheets){if(!sheet.grid.some(r=>r?.some(v=>C.txt(v))))continue;const result=C.parseSheet(sheet.grid,file.name,sheet.name);rows.push(...result.rows);errors.push(...result.errors);statements.push(...result.statements);other+=result.other;}}catch(e){errors.push(file.name+': '+e.message);}}
 if(generation!==importGeneration)return;const result=C.merge(state.rows,rows),known=new Set(state.rows.map(r=>r.id));pending={baseRevision:state.revision,result,errors,statements,other,files:filesList,newRows:result.rows.filter(r=>!known.has(r.id))};if(!rows.length&&!errors.length)pending.errors.push('Tiedostoista ei löytynyt kustannuspaikkojen 1682 tai 1683 tositerivejä.');if(view==='import')$('#import-preview').innerHTML=preview();}
function filteredRows(){const q=filter.search.toLowerCase();return state.rows.filter(r=>(!filter.cc||r.cc===filter.cc)&&(!filter.month||r.date.startsWith(filter.month))&&(!q||[r.description,r.account,r.accountName,r.voucher,r.note].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date)||a.account.localeCompare(b.account));}
function transactionTable(){const rows=filteredRows();return `<p class="sub">${rows.length} riviä · kaikkien näkyvien rivien netto ${euro(rows.reduce((a,r)=>a+r.debit-r.credit,0))}</p>${table(['Päivä','KP / tili','Tosite / Jnro','Selite','Debet','Kredit','Palkkapohjaan','Toiminnot'],rows.map(r=>[dsp(r.date),`${esc(r.cc)} / ${esc(r.account)}<br><span class="sub">${esc(r.accountName)}</span>`,`${esc(r.voucher)} / ${esc(r.line||'puuttuu')}`,`<div class="wrap">${esc(r.description)}<br><span class="sub">${esc(r.source)} · ${esc(r.sheet)} · rivi ${r.sourceRow||''}</span>${r.note?'<br>'+esc(r.note):''}</div>`,n(r.debit),n(r.credit),`${n(r.eligible!==null?r.eligible:C.payroll(r,state.settings)?r.debit-r.credit:0)}${C.payroll(r,state.settings)?`<span class="tag ${r.reviewed?'':'rose'}">${r.reviewed?'Tarkistettu':'Tarkistamatta'}</span>`:''}`,button('edit-row','Tarkista','smallbutton',`data-id="${esc(r.id)}"`)]))}`;}
function transactions(){const months=[...new Set(state.rows.map(r=>r.date.slice(0,7)))].sort();return head('Tapahtumat','Kirjanpidon tapahtumat ja palkkapohjan tarkistus.',button('add-row','+ Lisää käsin'))+warnings()+`<section class="panel"><div class="toolbar"><label>Hae tapahtumia<input id="search" value="${esc(filter.search)}" placeholder="Selite, tili tai tosite"></label><label>Kustannuspaikka<select id="filter-cc"><option value="">Kaikki</option>${['1682','1683'].map(c=>`<option ${filter.cc===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Kuukausi<select id="filter-month"><option value="">Kaikki</option>${months.map(m=>`<option ${filter.month===m?'selected':''}>${m}</option>`).join('')}</select></label>${button('export-transactions','Vie näkyvät CSV')}</div><div id="transaction-table">${transactionTable()}</div></section>`;}
function funding(){const t=C.totals(state.rows,state.settings);return head('Rahoituksen seuranta','Yksi tapahtuma rahoittajaa ja maksatusjaksoa kohti. Päivitä sitä hakemuksen edetessä.',button('add-funding','+ Lisää rahoituserä','primary'))+warnings()+`<p class="notice">Tähän kirjataan maksatushakemukset ja maksatuspäätökset. Hankkeen koko rahoituspäätöstä ei kirjata maksatuseräksi. Tyhjä summa tarkoittaa, ettei vaihetta ole vielä kirjattu.</p><div class="fundingcards">${['JTF','Tulevaisuusrahasto'].map((name,i)=>{const f=C.fundingTotal(state.funding,name),calc=i?t.future:t.jtf;return `<section class="panel"><div class="eyebrow">${i?'20 %':'80 %'} rahoitusosuus</div><h2>${name}</h2>${line('Laskennallinen osuus',euro(calc))}${line('Haettu',euro(f.applied))}${line('Päätetty',euro(f.decided))}${line('Saatu',euro(f.received))}${line('Laskennallisesti vielä haettavana',euro(Math.max(0,calc-f.applied)))}${line('Haettu, päätöstä odottava¹',euro(state.funding.filter(x=>x.funder===name&&x.decided===null).reduce((a,x)=>a+(x.applied||0),0)))}${line('Päätetty, vielä maksamatta',euro(state.funding.filter(x=>x.funder===name).reduce((a,x)=>a+Math.max(0,(x.decided||0)-(x.received||0)),0)))}${line('Laskennallisesti vielä saamatta',euro(Math.max(0,calc-f.received)))}${f.received>calc?`<p class="notice warn">Saatu rahoitus ylittää tämän kustannuspohjan arvion ${euro(f.received-calc)}.</p>`:''}</section>`;}).join('')}</div><p class="sub">¹ Koko haettu määrä odottaa päätöstä, kun päätetty summa on tyhjä. Päätös 0 € on kirjattu hylkäys. Laskennallinen saamatta oleva osuus ei ole vahvistettu saatava. Saannot näytetään kaikilta kirjatuilta jaksoilta.</p><section class="panel"><h2>Rahoituserät</h2>${table(['Rahoittaja / jakso','Haettu','Päätetty','Saatu','Lisätieto',''],state.funding.map(f=>[`${esc(f.funder)}<br><span class="sub">${dsp(f.from)}–${dsp(f.to)}</span>`,`${f.applied===null?'Ei kirjattu':n(f.applied)}<br><span class="sub">${dsp(f.applicationDate)}</span>`,`${f.decided===null?'Ei kirjattu':n(f.decided)}<br><span class="sub">${dsp(f.decisionDate)}</span>`,`${f.received===null?'Ei kirjattu':n(f.received)}<br><span class="sub">${dsp(f.paymentDate)}</span>`,`<div class="wrap">${esc(f.note)}</div>`,button('edit-funding','Muokkaa','smallbutton',`data-id="${esc(f.id)}"`)]))}</section>`;}
const reportFields=[['a','1682 menot'],['b','1683 menot'],['actual','Menot yhteensä'],['wage','Palkkapohja'],['side','Vakiosivukulut'],['salary','Hyväksyttävät palkat, arvio'],['flat','Flat rate'],['basis','Kustannuspohja, arvio'],['jtf','JTF, arvio'],['future','Tulevaisuusrahasto, arvio'],['margin','FR-marginaali']];
function reports(){const rr=C.report(state.rows,state.settings,mode);return head('Raportit','Summat perustuvat tositeriveihin. Prosenttilaskenta pyöristetään kuukausittain sentteihin.',button('export-report','Vie yhteenveto CSV','primary'))+`<section class="panel"><div class="toolbar"><label>Näkymä<select id="report-mode"><option value="monthly" ${mode==='monthly'?'selected':''}>Kuukausittain</option><option value="yearly" ${mode==='yearly'?'selected':''}>Vuosittain</option><option value="total" ${mode==='total'?'selected':''}>Kumulatiivinen koko hanke</option></select></label><span class="sub">${state.settings.cutoff?'Katkaisu '+dsp(state.settings.cutoff):'Kaikki tuodut hankekauden kuukaudet'}</span></div>${table(['Jakso',...reportFields.map(x=>x[1])],rr.map(r=>[r.period,...reportFields.map(([k])=>n(r[k]))]))}</section><section class="panel"><h2>Rahoituksen yhteenveto</h2>${table(['Rahoittaja','Laskennallinen','Haettu','Päätetty','Saatu'],['JTF','Tulevaisuusrahasto'].map((name,i)=>{const f=C.fundingTotal(state.funding,name),t=C.totals(state.rows,state.settings);return[name,n(i?t.future:t.jtf),n(f.applied),n(f.decided),n(f.received)];}))}<p class="sub">CSV-yhteenveto sisältää myös rahoituksen vaiheet ja budjettivertailun. CSV avautuu Excelissä.</p></section>`;}
const field=(name,label,type='text',value='',required=false,extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;
function settings(){const s=state.settings;return head('Asetukset ja varmuuskopio','Hankesuunnitelman lähtötiedot ja tämän selaimen talousaineisto.')+`<section class="panel"><h2>Hankkeen lähtötiedot</h2><p class="sub">Lähde: hyväksytty hankesuunnitelma 31.3.2026, sivut 2, 17, 26–27 ja 32–36. Erillisiä rahoituspäätöksiä ei ollut rakennusaineistossa.</p><form id="settings-form"><div class="formgrid">${field('start','Hanke alkaa','date',s.start,true)}${field('end','Hanke päättyy','date',s.end,true)}${field('budget','Kokonaisbudjetti €','number',amt(s.budget),true,'step="0.01" min="0.01"')}${field('salaryBudget','Palkkabudjetti €','number',amt(s.salaryBudget),true,'step="0.01" min="0"')}${field('flatBudget','Flat rate -budjetti €','number',amt(s.flatBudget),true,'step="0.01" min="0"')}${field('jtfCap','JTF:n suunnitelman mukainen osuus €','number',amt(s.jtfCap),true,'step="0.01" min="0"')}${field('futureCap','Tulevaisuusrahaston suunniteltu osuus €','number',amt(s.futureCap),true,'step="0.01" min="0"')}${field('sideRate','Vakiosivukulut %','number',s.sideRate,true,'step="0.01" min="0" max="100"')}${field('salaryAccounts','Palkkapohjan tilit (pilkulla eroteltuina)','text',s.salaryAccounts.join(', '),true)}<div><p class="sub">Oletus: 5002. Kirjanpitoon jo kohdistettua osa-aikaisen palkkaa ei kerrota 80 prosentilla uudestaan. Lomaraha ja tukikelvottomat erät poistetaan palkkapohjasta tapahtumakohtaisesti.</p><span class="tag">Flat rate 40 % · JTF 80 % · Tulevaisuusrahasto 20 %</span></div>${field('cutoff','Viimeinen kokonaan kirjattu kuukausi','month',s.cutoff.slice(0,7))}${field('forecastMonthly','Tulevien kuukausien menoarvio €/kk (valinnainen)','number',amt(s.forecastMonthly),false,'step="0.01" min="0"')}</div><p class="sub">Tyhjä menoarvio käyttää viimeisten enintään kolmen valmiin kuukauden keskiarvoa. Vahvista, että molempien kustannuspaikkojen pääkirjat ovat mukana. Katkaisukuukauden jälkeiset rivit säilyvät tapahtumissa, mutta eivät sisälly yhteenvetoon.</p><button class="primary" type="submit">Tallenna asetukset</button></form></section><section class="panel"><h2>Varmuuskopio ja palautus</h2><p>Tiedot ovat vain tässä selaimessa. Vie varmuuskopio säännöllisesti ja ennen selaimen tietojen tyhjentämistä tai laitteen vaihtoa.</p><div class="actions">${button('backup','Vie varmuuskopio','primary')}${button('restore','Palauta varmuuskopio')}${button('clear','Tyhjennä paikallinen data','danger')}</div><input type="file" id="restore-file" accept=".json" hidden><p class="sub" style="margin-top:16px">JSON-varmuuskopio sisältää pääkirjarivit, palkkapohjan tarkistukset, rahoituserät, asetukset ja tuontihistorian. Se sisältää taloustietojasi. Palautus korvaa nykyiset tiedot vahvistuksen jälkeen.</p></section><section class="panel"><h2>Laskennan periaatteet</h2><p>Palkkapohja + 26,44 % vakiosivukuluja = hyväksyttävien palkkojen arvio. Siitä lasketaan 40 % flat rate. Näiden yhteismäärä jaetaan JTF:n 80 % ja Tulevaisuusrahaston 20 % osuuksiin.</p><p>Kirjanpidon sivukulut sisältyvät toteutuneisiin menoihin, eivät uudelleen laskennalliseen kustannuspohjaan. Palkkapohjan tarkistus ei muuta alkuperäisiä kirjanpitorivejä. Lopullisen tukikelpoisuuden ratkaisee rahoittaja.</p><p class="sub">Suunnitelman kokonaismäärät säilytetään sellaisinaan: JTF 247 916 € ja Tulevaisuusrahasto 61 980 €. Ne poikkeavat hieman kokonaisbudjetin tarkasta prosenttijaosta suunnitelman pyöristysten vuoksi. Maksatusarvioita ei rajata automaattisesti näihin summiin.</p></section>`;}
function render(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#save-state').textContent=storageError?'Paikallinen tallennus ei toimi':`${state.rows.length} riviä · tallessa tässä selaimessa`;$('#main').innerHTML=(storageError?`<div class="notice error">${esc(storageError)}. Tietoja ei voi tallentaa. Kokeile normaalia selainikkunaa ja salli paikallinen tallennus.</div>`:'')+({overview,import:importPage,transactions,funding,reports,settings}[view]());}
function modal(title,body){const d=$('#modal');d.innerHTML=`<h2 id="modal-title">${title}</h2>${body}`;d.showModal();}
const cancel=()=>button('close-modal','Peruuta');
function confirmAction(title,body,fn,label='Vahvista'){modal(title,`<p>${body}</p><div class="modalactions">${cancel()}${button('confirm',label,'berry')}</div>`);$('#modal [data-action="confirm"]').onclick=async()=>{const ok=await fn();if(ok!==false)$('#modal').close();};}
function editRow(id){const r=state.rows.find(r=>r.id===id);if(!r)return;const wage=r.eligible!==null?r.eligible:C.payroll(r,state.settings)?r.debit-r.credit:0;modal('Tarkista tapahtuma',`<p>${esc(r.description)}<br><span class="sub">${dsp(r.date)} · ${esc(r.cc+' / '+r.account+' / '+r.voucher)} · netto ${euro(r.debit-r.credit)}</span></p><form id="row-form" data-id="${esc(id)}">${field('eligible','Palkkapohjaan hyväksyttävä määrä €, ilman sivukuluja ja lomarahaa','number',amt(wage),true,'step="0.01"')}<p class="sub">Kredit-oikaisun palkkapohja voi olla negatiivinen. Älä sisällytä toteutuneita sivukuluja tähän. Alkuperäinen kirjanpitosumma säilyy.</p><label>Perustelu / lisätieto<textarea name="note" rows="3">${esc(r.note)}</textarea></label><label class="check"><input name="reviewed" type="checkbox" ${r.reviewed?'checked':''}> Olen tarkistanut palkkapohjan, lomarahaosuuden ja kohdistuksen.</label><div class="modalactions">${button('delete-row','Poista kirjanpitorivi','danger',`data-id="${esc(id)}"`)}${cancel()}<button class="primary">Tallenna tarkistus</button></div></form>`);}
function addRow(){modal('Lisää kirjanpitorivi',`<form id="manual-form"><div class="formgrid">${field('date','Päivämäärä','date','',true)}<label>Kustannuspaikka<select name="cc"><option>1682</option><option>1683</option></select></label>${field('account','Tili','text','',true,'pattern="[0-9]{3,8}"')}${field('accountName','Tilin nimi','text','',true)}${field('voucher','Tosite','text','',true)}${field('line','Jnro (jos tiedossa)')}${field('kind','Tl (jos tiedossa)')}${field('description','Selite','text','',true)}${field('debit','Debet €','number','0',true,'step="0.01"')}${field('credit','Kredit €','number','0',true,'step="0.01"')}</div><div class="modalactions">${cancel()}<button class="primary">Lisää rivi</button></div></form>`);}
function editFunding(id){const f=state.funding.find(x=>x.id===id)||{id:'',funder:'JTF',from:'',to:'',applied:null,decided:null,received:null,applicationDate:'',decisionDate:'',paymentDate:'',note:''};modal(f.id?'Muokkaa rahoituserää':'Lisää rahoituserä',`<form id="funding-form" data-id="${esc(f.id)}"><label>Rahoittaja<select name="funder"><option ${f.funder==='JTF'?'selected':''}>JTF</option><option ${f.funder==='Tulevaisuusrahasto'?'selected':''}>Tulevaisuusrahasto</option></select></label><div class="formgrid">${field('from','Maksatusjakson alku','date',f.from,true)}${field('to','Maksatusjakson loppu','date',f.to,true)}${field('applied','Haettu summa €','number',amt(f.applied),false,'step="0.01" min="0"')}${field('applicationDate','Hakupäivä','date',f.applicationDate)}${field('decided','Päätetty summa €','number',amt(f.decided),false,'step="0.01" min="0"')}${field('decisionDate','Päätöspäivä','date',f.decisionDate)}${field('received','Saatu summa yhteensä €','number',amt(f.received),false,'step="0.01" min="0"')}${field('paymentDate','Maksupäivä (viimeisin)','date',f.paymentDate)}</div><p class="sub">Saman jakson osamaksut päivitetään saatuun yhteissummaan. Erittely voidaan kirjata lisätietoihin. Tyhjä = vaihe puuttuu; 0 € = kirjattu nollamäärä.</p><label>Lisätieto<textarea name="note" rows="3">${esc(f.note)}</textarea></label><div class="modalactions">${f.id?button('delete-funding','Poista erä','danger',`data-id="${esc(f.id)}"`):''}${cancel()}<button class="primary">Tallenna rahoituserä</button></div></form>`);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(){download('Ilmastovisio-varmuuskopio-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');}
function exportReport(){const rr=C.report(state.rows,state.settings,mode),t=C.totals(state.rows,state.settings),s=state.settings;const rows=[['Ilmastovisio J11721','Laskennallinen arvio'],['Katkaisu',s.cutoff||'Kaikki tuodut hankekauden kuukaudet'],['Jakso',...reportFields.map(x=>x[1])],...rr.map(r=>[r.period,...reportFields.map(([k])=>(r[k]/100).toFixed(2).replace('.',','))]),[],['Rahoittaja','Laskennallinen €','Haettu €','Päätetty €','Saatu €'],...['JTF','Tulevaisuusrahasto'].map((name,i)=>{const f=C.fundingTotal(state.funding,name);return[name,...[i?t.future:t.jtf,f.applied,f.decided,f.received].map(x=>(x/100).toFixed(2).replace('.',','))];}),[],['Budjetti €',s.budget/100],['Kustannuspohja €',t.basis/100],['Budjetista jäljellä €',(s.budget-t.basis)/100],['Budjetista käytetty %',100*t.basis/s.budget],['Laskennan huomautukset'],...issues().map(x=>[x])];download('Ilmastovisio-yhteenveto.csv',C.csv(rows),'text/csv;charset=utf-8');}
async function restore(file){try{if(file.size>50*1024*1024)throw Error('Varmuuskopio on liian suuri (enintään 50 Mt).');const loaded=C.validateState(JSON.parse(await file.text()));confirmAction('Palauta varmuuskopio',`${loaded.rows.length} tositeriviä ja ${loaded.funding.length} rahoituserää. Palautus korvaa tämän selaimen nykyiset tiedot. Vie ensin nykyinen varmuuskopio, jos haluat säilyttää sen.`,()=>commit(loaded,'Varmuuskopio palautettu.'),'Korvaa nykyiset tiedot');}catch(e){notify('Palautus estetty: '+e.message);}}
async function action(a,el){if(a.startsWith('nav-'))return go(a.slice(4));switch(a){case'close-modal':$('#modal').close();break;case'add-funding':editFunding('');break;case'edit-funding':editFunding(el.dataset.id);break;case'edit-row':editRow(el.dataset.id);break;case'add-row':addRow();break;case'backup':backup();break;case'restore':$('#restore-file').click();break;case'export-report':exportReport();break;case'export-transactions':download('Ilmastovisio-tapahtumat.csv',C.csv([['Päivämäärä','Kustannuspaikka','Tili','Tilin nimi','Tosite','Jnro','Tl','Selite','Debet','Kredit','Palkkapohja','Tarkistettu','Perustelu'],...filteredRows().map(r=>[r.date,r.cc,r.account,r.accountName,r.voucher,r.line,r.kind,r.description,(r.debit/100).toFixed(2).replace('.',','),(r.credit/100).toFixed(2).replace('.',','),amt(r.eligible),r.reviewed?'kyllä':'ei',r.note])]),'text/csv;charset=utf-8');break;case'download-template':download('Ilmastovisio-tuontipohja.csv',C.csv([['Päivämäärä','Kustannuspaikka','Tili','Tilin nimi','Tosite','Jnro','Tl','Selite','Debet','Kredit']]),'text/csv;charset=utf-8');break;case'cancel-import':importGeneration++;pending=null;render();break;case'commit-import':{if(!pending||pending.errors.length||pending.result.conflicts.length)return;const p=pending;if(p.baseRevision!==state.revision){pending=null;render();notify('Tiedot muuttuivat esikatselun jälkeen. Valitse tiedosto uudelleen.');return;}const next=clone();next.rows=p.result.rows;for(const st of p.statements)if(!next.statements.some(x=>JSON.stringify(x)===JSON.stringify(st)))next.statements.push(st);next.imports.push({date:new Date().toISOString(),source:p.files.join(', '),added:p.result.added,duplicates:p.result.duplicates});lastImport=`Tuonti valmis: ${p.result.added} uutta riviä, ${p.result.duplicates} jo ennestään.`;if(await commit(next,lastImport)){pending=null;render();}break;}case'clear':confirmAction('Tyhjennä paikallinen data','Kaikki pääkirjarivit, rahoituserät, tuontihistoria ja omat asetukset poistetaan tästä selaimesta. Toimintoa ei voi perua ilman varmuuskopiota.',()=>{pending=null;importGeneration++;return commit(C.empty(),'Paikalliset tiedot tyhjennetty.');},'Tyhjennä kaikki');break;case'delete-row':{const id=el.dataset.id;$('#modal').close();confirmAction('Poista kirjanpitorivi','Rivi poistetaan laskennasta. Myöhempi pääkirjan tuonti voi lisätä sen uudelleen. Jos haluat vain poistaa summan palkkapohjasta, aseta palkkapohjan määräksi 0 €.',()=>{const x=clone();x.rows=x.rows.filter(r=>r.id!==id);return commit(x,'Rivi poistettu.');},'Poista rivi');break;}case'delete-funding':{const id=el.dataset.id;$('#modal').close();confirmAction('Poista rahoituserä','Erä poistetaan rahoituksen seurannasta.',()=>{const x=clone();x.funding=x.funding.filter(r=>r.id!==id);return commit(x,'Rahoituserä poistettu.');},'Poista erä');break;}}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){go(nav.dataset.view);return;}const b=e.target.closest('[data-action]');if(b&&b.dataset.action!=='confirm'){e.preventDefault();Promise.resolve(action(b.dataset.action,b)).catch(x=>notify(x.message));}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='ledger-files')loadFiles([...t.files]).catch(x=>notify(x.message));if(t.id==='restore-file'&&t.files[0]){restore(t.files[0]);t.value='';}if(t.id==='filter-cc'||t.id==='filter-month'){filter[t.id==='filter-cc'?'cc':'month']=t.value;$('#transaction-table').innerHTML=transactionTable();}if(t.id==='report-mode'){mode=t.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filter.search=e.target.value;$('#transaction-table').innerHTML=transactionTable();}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=Object.fromEntries(new FormData(form)),next=clone();try{if(form.id==='settings-form'){const s=next.settings;for(const k of ['budget','salaryBudget','flatBudget','jtfCap','futureCap'])s[k]=C.money(f[k]);if(s.budget!==s.salaryBudget+s.flatBudget)throw Error('Palkkabudjetin ja flat rate -budjetin summan pitää vastata kokonaisbudjettia.');if(s.budget!==s.jtfCap+s.futureCap)throw Error('Rahoitusosuuksien summan pitää vastata kokonaisbudjettia.');s.start=f.start;s.end=f.end;if(s.start>s.end)throw Error('Hankkeen loppu on ennen alkua.');s.sideRate=Number(f.sideRate);s.salaryAccounts=f.salaryAccounts.split(',').map(x=>x.trim()).filter(Boolean);s.cutoff=C.monthEnd(f.cutoff);if(s.cutoff&&(s.cutoff<s.start||s.cutoff>s.end))throw Error('Valitse hankekauteen kuuluva kuukausi.');s.forecastMonthly=f.forecastMonthly===''?null:C.money(f.forecastMonthly);await commit(next,'Asetukset tallennettu.');}
 if(form.id==='row-form'){const r=next.rows.find(r=>r.id===form.dataset.id);const val=C.money(f.eligible);if(val!==0&&(Math.sign(val)!==Math.sign(r.debit-r.credit)||Math.abs(val)>Math.abs(r.debit-r.credit)))throw Error('Palkkapohjan pitää olla nollan ja kirjanpitorivin nettosumman välillä.');if(val!==0&&(r.cc!=='1682'||!C.expense(r)))throw Error('Palkkapohjaan voi lisätä vain kustannuspaikan 1682 kulurivejä.');r.eligible=val;r.note=f.note;r.reviewed=f.reviewed==='on';if(await commit(next,'Palkkapohjan tarkistus tallennettu.'))$('#modal').close();}
 if(form.id==='manual-form'){const r={...f,date:C.date(f.date),debit:C.money(f.debit),credit:C.money(f.credit),source:'Käsin syötetty',sheet:'',sourceRow:0,eligible:null,reviewed:false,note:''};if(!r.date)throw Error('Virheellinen päivämäärä');r.id=C.baseKey(r)+(r.line?'':'|'+JSON.stringify([r.debit,r.credit,r.description]))+'#1';const m=C.merge(next.rows,[r]);if(m.duplicates||m.conflicts.length)throw Error('Tosite on jo olemassa. Tarkista tapahtumat.');next.rows=m.rows;if(await commit(next,'Rivi lisätty.'))$('#modal').close();}
 if(form.id==='funding-form'){const id=form.dataset.id||crypto.randomUUID(),r={...f,id};if(r.from>r.to)throw Error('Maksatusjakson loppu on ennen alkua.');if(next.funding.some(x=>x.id!==id&&x.funder===r.funder&&x.from===r.from&&x.to===r.to))throw Error('Tämä maksatusjakso on jo olemassa. Muokkaa aiempaa erää.');for(const [amount,day]of [['applied','applicationDate'],['decided','decisionDate'],['received','paymentDate']]){r[amount]=f[amount]===''?null:C.money(f[amount]);if(r[amount]!==null&&!r[day])throw Error('Lisää summalle myös vastaava päivämäärä.');if(r[amount]===null&&r[day])throw Error('Lisää päivämäärälle myös vastaava summa.');}if([r.applied,r.decided,r.received].every(x=>x===null))throw Error('Kirjaa vähintään yksi summa.');if(r.applicationDate&&r.decisionDate&&r.applicationDate>r.decisionDate)throw Error('Päätöspäivä on ennen hakupäivää.');if(r.decisionDate&&r.paymentDate&&r.decisionDate>r.paymentDate)throw Error('Maksupäivä on ennen päätöspäivää.');next.funding=next.funding.filter(x=>x.id!==id);next.funding.push(r);if(await commit(next,'Rahoituserä tallennettu.'))$('#modal').close();}
 }catch(x){notify(x.message);}});
(async()=>{try{db=await openDB();const saved=await getDB();if(saved)state=C.validateState(saved);db.onversionchange=()=>{db.close();storageError='Tietokanta muuttui. Päivitä sivu.';render();};}catch(e){storageError=e.message||'Selaimen tietokantaa ei voi avata';}render();})();
})();
